import { useRef, useState } from "react";
import { Collection } from "@collections/models/Collection";
import CollectionService from "@collections/services/CollectionService";
import { useAuth } from "@shared/contexts/AuthContext";

export function useFetchCollections() {
  const { user, authHasBeenChecked } = useAuth();
  const [currentSkip, setCurrentSkip] = useState<number>(0);
  const [currentPageSize] = useState<number>(10);
  const [collections, setCollections] = useState<Collection[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState<boolean>(false);
  const [totalCount, setTotalCount] = useState<number>(0);
  const [hasMore, setHasMore] = useState<boolean>(true);

  // Prevent duplicate in-flight fetches across StrictMode re-renders.
  const isFetching = useRef(false);

  const loadMoreCollections = async () => {
    if (isFetching.current || loading || !hasMore || !authHasBeenChecked)
      return;
    isFetching.current = true;
    setLoading(true);
    try {
      const response = await CollectionService.getList(
        currentSkip,
        currentPageSize,
        searchTerm,
        user?.id,
      );

      if (!response || response.data.length === 0) {
        setHasMore(false);
      } else {
        setCollections((prev) => [...prev, ...response.data]);
        setCurrentSkip((prevSkip) => prevSkip + response.data.length);
        setTotalCount(response.count || 0);
      }
    } catch (error: any) {
      console.error("Error fetching collections:", error.message);
    } finally {
      setLoading(false);
      isFetching.current = false;
    }
  };

  return {
    collections,
    searchTerm,
    setSearchTerm,
    loading,
    hasMore,
    totalCount,
    loadMoreCollections,
  };
}
